/* SPDX-License-Identifier: GPL-2.0-only */
/* Private source-only MSI context. No IRQ/domain funding or admission. */
#ifndef LSF_STREAM_MSI_CONTEXT_PRIVATE_H
#define LSF_STREAM_MSI_CONTEXT_PRIVATE_H
struct device;
struct attribute_group;
#define LSF_STREAM_MSI_CONTEXT_DR 0x181u
#define LSF_STREAM_MSI_GROUP_DR 0x182u
#define LSF_STREAM_MSI_CONTEXT 1u
#define LSF_STREAM_MSI_GROUP 2u
#define LSF_STREAM_MSI_UNLINKED 0
#define LSF_STREAM_MSI_BEFORE_RELEASE 1
#define LSF_STREAM_MSI_AFTER_RELEASE 2
struct lsf_stream_msi_plan {
    unsigned int slot[2];
    unsigned long long generation[2];
};
int lsf_factory_stream_msi_selected(struct device *);
int lsf_factory_stream_msi_prepare(struct device *, struct lsf_stream_msi_plan *);
void *lsf_factory_stream_msi_take(struct device *, const struct lsf_stream_msi_plan *, unsigned int);
void lsf_factory_stream_msi_discard(struct device *, struct lsf_stream_msi_plan *);
int lsf_factory_stream_msi_envelope(const void *, struct device *, struct device **, unsigned int *);
int lsf_factory_stream_msi_return(const void *, struct device *);
int lsf_prepaid_stream_msi_payload_geometry(unsigned long *, unsigned long *);
int lsf_prepaid_stream_msi_group_geometry(unsigned long *, unsigned long *);
int lsf_prepaid_stream_msi_devres_geometry(unsigned int, unsigned long *, unsigned long *, unsigned long *);
void *lsf_prepaid_stream_msi_devres_allocate(struct device *, unsigned int,
    const struct lsf_stream_msi_plan *, void (*)(struct device *, void *));
int lsf_prepaid_stream_msi_resource_classify(struct device *, const void *, unsigned int *);
int lsf_prepaid_stream_msi_devres_validate(struct device *, const void *, int);
int lsf_prepaid_stream_msi_devres_retire(struct device *, void *, int);
int lsf_prepaid_stream_msi_release_known(unsigned int, void (*)(struct device *, void *));
int lsf_prepaid_stream_msi_group_release_known(void (*)(struct device *, void *));
int lsf_prepaid_stream_msi_group_known(const struct attribute_group *);
int lsf_prepaid_stream_msi_group_payload_known(const void *, int);
int lsf_prepaid_stream_msi_payload_known(struct device *, const void *, int);
int lsf_prepaid_stream_msi_setup_device_data(struct device *);
void lsf_factory_stream_constructor_retain_unknown(void);
int lsf_prepaid_stream_msi_add_group(struct device *, const struct attribute_group *,
    const struct lsf_stream_msi_plan *);
#endif

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after the original stream constructors; original bank/records only. */
#include <net/lsf_stream_msi_context_private.h>

static int lsf_stream_msi_parent_locked(struct device *dev,
    struct lsf_stream_rx_state **state, struct lsf_prepaid_ticket *parent)
{
    const void *address;
    struct lsf_prepaid_view *record;
    int result;
    lockdep_assert_held(&pool_lock);
    result = lsf_factory_device_core_parent(dev, offsetof(struct pci_dev, dev), parent, &address);
    if (result != 1) return result;
    *state = lsf_stream_rx_current_locked();
    if (!*state || !factory.device ||
        (*state)->owner.slot != factory.device->key.slot ||
        (*state)->owner.generation != factory.device->key.generation) return -EOPNOTSUPP;
    record = lsf_device_record(&factory.pool, (*state)->owner, *parent, LSF_DEVICE_PCI);
    if (!record || record->bytes < sizeof(struct pci_dev) ||
        (record->deferred != LSF_PREPAID_PUBLISHED && record->deferred != LSF_PREPAID_QUEUED) ||
        dev != &((struct pci_dev *)address)->dev) return -EOPNOTSUPP;
    return 1;
}

int lsf_factory_stream_msi_selected(struct device *dev)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent;
    unsigned long flags;
    int result;
    if (!lsf_factory_selected_consumer()) return 0;
    spin_lock_irqsave(&pool_lock, flags);
    result = lsf_stream_msi_parent_locked(dev, &state, &parent);
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

static unsigned int lsf_stream_msi_kind(unsigned int role)
{
    return role == LSF_STREAM_MSI_CONTEXT ? LSF_STREAM_MSI_CONTEXT_DR :
        role == LSF_STREAM_MSI_GROUP ? LSF_STREAM_MSI_GROUP_DR : 0;
}

static struct lsf_prepaid_view *lsf_stream_msi_ticket_locked(
    struct lsf_stream_rx_state *state, struct lsf_prepaid_ticket parent,
    const struct lsf_stream_msi_plan *plan, unsigned int role)
{
    struct lsf_prepaid_view *record;
    unsigned long bytes, alignment, offset;
    unsigned int index = role - 1u, kind = lsf_stream_msi_kind(role);
    if (!kind || !plan || index > 1u || !plan->slot[0] || !plan->slot[1] ||
        plan->slot[0] == plan->slot[1] ||
        lsf_prepaid_stream_msi_devres_geometry(role, &bytes, &alignment, &offset)) return NULL;
    record = lsf_device_record(&factory.pool, state->owner,
        (struct lsf_prepaid_ticket){plan->slot[index], plan->generation[index]}, kind);
    if (!record || record->bytes != ((bytes + 63u) & ~63ul) ||
        record->cache_bucket != parent.slot || record->cache_anchor != parent.generation ||
        record->security_cache_location != plan->slot[0] ||
        record->security_cache_identity != plan->generation[0]) return NULL;
    return record;
}

int lsf_factory_stream_msi_prepare(struct device *dev, struct lsf_stream_msi_plan *plan)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent, ticket;
    struct lsf_prepaid_view *record;
    unsigned long flags, bytes[2], alignment[2], data_offset;
    u64 offset;
    unsigned int index;
    int result = -EOPNOTSUPP;
    if (!plan) return -EINVAL;
    *plan = (struct lsf_stream_msi_plan){};
    for (index = 0; index < 2u; ++index)
        if (lsf_prepaid_stream_msi_devres_geometry(index + 1u, &bytes[index],
            &alignment[index], &data_offset)) return result;
    spin_lock_irqsave(&pool_lock, flags);
    if (lsf_stream_msi_parent_locked(dev, &state, &parent) != 1 ||
        !lsf_stream_bind_current_locked(state) || dev != &state->pci->dev ||
        state->pci->is_managed) goto out; /* Managed action has no funded port. */
    for (index = 0; index < 2u; ++index) {
        result = lsf_stream_constructor_allocate_locked(state, lsf_stream_msi_kind(index + 1u),
            parent, bytes[index], alignment[index], &ticket, &offset);
        if (result != 1) {
            /* No view escaped. Finish only the already-reserved PRIVATE prefix;
             * its cursor/record/backing is neither rewound nor reused. */
            if (index && !lsf_device_finish(&factory.pool, state->owner,
                (struct lsf_prepaid_ticket){plan->slot[0], plan->generation[0]},
                LSF_STREAM_MSI_CONTEXT_DR)) {
                factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
            }
            *plan = (struct lsf_stream_msi_plan){};
            goto out;
        }
        plan->slot[index] = ticket.slot; plan->generation[index] = ticket.generation;
    }
    for (index = 0; index < 2u; ++index) {
        record = &factory.pool.records[plan->slot[index]];
        record->security_cache_location = plan->slot[0];
        record->security_cache_identity = plan->generation[0];
    }
    result = 1;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

void *lsf_factory_stream_msi_take(struct device *dev,
    const struct lsf_stream_msi_plan *plan, unsigned int role)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent;
    struct lsf_prepaid_view *record;
    unsigned long flags;
    void *result = NULL;
    spin_lock_irqsave(&pool_lock, flags);
    if (lsf_stream_msi_parent_locked(dev, &state, &parent) != 1 ||
        !lsf_stream_bind_current_locked(state) ||
        !(record = lsf_stream_msi_ticket_locked(state, parent, plan, role)) ||
        record->deferred != LSF_PREPAID_PRIVATE ||
        !lsf_stream_msi_ticket_locked(state, parent, plan,
            role == LSF_STREAM_MSI_CONTEXT ? LSF_STREAM_MSI_GROUP : LSF_STREAM_MSI_CONTEXT))
        goto out;
    if (!lsf_device_publish(&factory.pool, state->owner,
        (struct lsf_prepaid_ticket){plan->slot[role - 1u], plan->generation[role - 1u]},
        lsf_stream_msi_kind(role))) goto out;
    result = (char *)page_address(factory.pages) + record->offset;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

void lsf_factory_stream_msi_discard(struct device *dev, struct lsf_stream_msi_plan *plan)
{
    struct lsf_stream_rx_state *state;
    struct lsf_prepaid_ticket parent;
    struct lsf_prepaid_view *record;
    struct lsf_stream_msi_plan saved;
    unsigned long flags;
    unsigned int index;
    if (!plan) return;
    saved = *plan; *plan = (struct lsf_stream_msi_plan){};
    spin_lock_irqsave(&pool_lock, flags);
    if (lsf_stream_msi_parent_locked(dev, &state, &parent) != 1) goto poison;
    for (index = 0; index < 2u; ++index) {
        if (!saved.slot[index]) continue;
        if (saved.slot[index] >= LSF_ALLOCATION_SLOTS) goto poison;
        record = &factory.pool.records[saved.slot[index]];
        if (record->generation != saved.generation[index] ||
            record->kind != lsf_stream_msi_kind(index + 1u) ||
            record->owner != state->owner.slot || record->owner_generation != state->owner.generation ||
            record->cache_bucket != parent.slot || record->cache_anchor != parent.generation ||
            record->security_cache_location != saved.slot[0] ||
            record->security_cache_identity != saved.generation[0]) goto poison;
        if (record->phase == LSF_PREPAID_RETURNED) continue;
        if (record->phase != LSF_PREPAID_LIVE) goto poison;
        if (record->deferred == LSF_PREPAID_PRIVATE &&
            !lsf_device_finish(&factory.pool, state->owner,
                (struct lsf_prepaid_ticket){saved.slot[index], saved.generation[index]},
                record->kind)) goto poison;
        /* Taken/published resources are retired ONLY by their actual native
         * free points. A failed or uncertain callback keeps them charged. */
    }
    goto out;
poison:
    factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1);
out:
    spin_unlock_irqrestore(&pool_lock, flags);
}

static struct lsf_prepaid_view *lsf_stream_msi_envelope_locked(const void *address,
    struct device *expected, struct device **actual, unsigned int *role,
    struct lsf_prepaid_ticket *ticket)
{
    struct lsf_prepaid_view *record, *parent, *first;
    unsigned long base, at = (unsigned long)address, bytes, alignment, data_offset;
    unsigned int index, selected_role;
    lockdep_assert_held(&pool_lock);
    if (!factory.pages || !factory.device) return NULL;
    base = (unsigned long)page_address(factory.pages);
    if (at < base || at - base >= LSF_BACKING_BYTES) return NULL;
    for (index = 1; index < LSF_ALLOCATION_SLOTS; ++index) {
        record = &factory.pool.records[index];
        if (record->offset != at - base) continue;
        selected_role = record->kind == LSF_STREAM_MSI_CONTEXT_DR ? LSF_STREAM_MSI_CONTEXT :
            record->kind == LSF_STREAM_MSI_GROUP_DR ? LSF_STREAM_MSI_GROUP : 0;
        if (!selected_role || !lsf_device_record(&factory.pool, factory.device->key,
            (struct lsf_prepaid_ticket){index, record->generation}, record->kind) ||
            record->deferred != LSF_PREPAID_PUBLISHED ||
            lsf_prepaid_stream_msi_devres_geometry(selected_role, &bytes, &alignment, &data_offset) ||
            record->bytes != ((bytes + 63u) & ~63ul)) return NULL;
        parent = lsf_device_record(&factory.pool, factory.device->key,
            (struct lsf_prepaid_ticket){record->cache_bucket, record->cache_anchor}, LSF_DEVICE_PCI);
        if (!parent || parent->bytes < sizeof(struct pci_dev) ||
            parent->offset > LSF_BACKING_BYTES - sizeof(struct pci_dev) ||
            (parent->deferred != LSF_PREPAID_PUBLISHED && parent->deferred != LSF_PREPAID_QUEUED)) return NULL;
        if (!record->security_cache_location || record->security_cache_location >= LSF_ALLOCATION_SLOTS)
            return NULL;
        first = &factory.pool.records[record->security_cache_location];
        if (first->kind != LSF_STREAM_MSI_CONTEXT_DR ||
            first->generation != record->security_cache_identity ||
            (first->phase != LSF_PREPAID_LIVE && first->phase != LSF_PREPAID_RETURNED) ||
            first->owner != record->owner || first->owner_generation != record->owner_generation ||
            first->cache_bucket != record->cache_bucket || first->cache_anchor != record->cache_anchor ||
            (selected_role == LSF_STREAM_MSI_CONTEXT && first != record) ||
            (selected_role == LSF_STREAM_MSI_GROUP && first == record)) return NULL;
        *actual = &((struct pci_dev *)(base + parent->offset))->dev;
        if (expected && expected != *actual) return NULL;
        *role = selected_role; *ticket = (struct lsf_prepaid_ticket){index, record->generation};
        return record;
    }
    return NULL;
}

int lsf_factory_stream_msi_envelope(const void *address, struct device *expected,
    struct device **actual, unsigned int *role)
{
    struct lsf_prepaid_ticket ticket;
    unsigned long flags;
    int result = 0;
    if (!actual || !role) return -EINVAL;
    *actual = NULL; *role = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_rx_address_locked(address)) goto out;
    result = lsf_stream_msi_envelope_locked(address, expected, actual, role, &ticket) ? 1 : -EOPNOTSUPP;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_stream_msi_return(const void *address, struct device *expected)
{
    struct lsf_prepaid_ticket ticket;
    struct device *actual;
    unsigned int role;
    unsigned long flags;
    int result = -EOPNOTSUPP;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_stream_msi_envelope_locked(address, expected, &actual, &role, &ticket) ||
        !lsf_device_queue(&factory.pool, factory.device->key, ticket, lsf_stream_msi_kind(role)) ||
        !lsf_device_finish(&factory.pool, factory.device->key, ticket, lsf_stream_msi_kind(role))) {
        factory.pool.poisoned = 1; WRITE_ONCE(factory.uncertain, 1); goto out;
    }
    result = 1;
out:
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after the actual native devres definitions and size helpers. */
#include <net/lsf_stream_msi_context_private.h>

int lsf_prepaid_stream_msi_devres_geometry(unsigned int role,
    unsigned long *bytes, unsigned long *alignment, unsigned long *data_offset)
{
    unsigned long payload, payload_alignment;
    size_t total;
    int result;
    if (!bytes || !alignment || !data_offset) return -EINVAL;
    if (role == LSF_STREAM_MSI_CONTEXT)
        result = lsf_prepaid_stream_msi_payload_geometry(&payload, &payload_alignment);
    else if (role == LSF_STREAM_MSI_GROUP)
        result = lsf_prepaid_stream_msi_group_geometry(&payload, &payload_alignment);
    else return -EOPNOTSUPP;
    if (result || !payload || !payload_alignment || payload_alignment > 64u ||
        (payload_alignment & (payload_alignment - 1u)) ||
        offsetof(struct devres, data) % payload_alignment ||
        __alignof__(struct devres) > 64u ||
        !check_dr_size(payload, &total) || total > ULONG_MAX - 63u)
        return -EOPNOTSUPP;
    *bytes = total; *alignment = __alignof__(struct devres);
    *data_offset = offsetof(struct devres, data);
    return 0;
}

void *lsf_prepaid_stream_msi_devres_allocate(struct device *dev, unsigned int role,
    const struct lsf_stream_msi_plan *plan, void (*release)(struct device *, void *))
{
    struct devres *dr;
    unsigned long total, alignment, data_offset, payload, payload_alignment;
    const char *name;
    if (!lsf_prepaid_stream_msi_release_known(role, release) ||
        lsf_prepaid_stream_msi_devres_geometry(role, &total, &alignment, &data_offset))
        return NULL;
    if (role == LSF_STREAM_MSI_CONTEXT) {
        if (lsf_prepaid_stream_msi_payload_geometry(&payload, &payload_alignment)) return NULL;
        name = "msi_device_data_release";
    } else {
        if (lsf_prepaid_stream_msi_group_geometry(&payload, &payload_alignment)) return NULL;
        name = "devm_attr_group_remove";
    }
    dr = lsf_factory_stream_msi_take(dev, plan, role);
    if (!dr) return NULL;
    /* Same __GFP_ZERO semantics as __devres_alloc_node, after complete native
     * bucket-rounded envelope admission. No heap wrapper or payload adoption. */
    memset(dr, 0, total);
    INIT_LIST_HEAD(&dr->node.entry);
    dr->node.release = release;
    set_node_dbginfo(&dr->node, name, payload);
    return dr->data;
}

int lsf_prepaid_stream_msi_resource_classify(struct device *dev,
    const void *resource, unsigned int *role)
{
    struct device *actual;
    unsigned long address;
    if (!resource || !role) return 0;
    address = (unsigned long)resource;
    if (address < offsetof(struct devres, data)) return -EOPNOTSUPP;
    return lsf_factory_stream_msi_envelope(
        (const void *)(address - offsetof(struct devres, data)), dev, &actual, role);
}

int lsf_prepaid_stream_msi_devres_validate(struct device *dev, const void *base, int phase)
{
    const struct devres *dr = base;
    struct device *actual;
    unsigned int role;
    int selected;
    if (phase != LSF_STREAM_MSI_UNLINKED && phase != LSF_STREAM_MSI_BEFORE_RELEASE &&
        phase != LSF_STREAM_MSI_AFTER_RELEASE) return -EINVAL;
    selected = lsf_factory_stream_msi_envelope(base, dev, &actual, &role);
    if (!selected) {
        /* Native list traversal already supplies a real outside devres node.
         * A known MSI callback attached to a protected device cannot launder
         * its outside heap block into the original paid context. */
        if (dev && lsf_factory_stream_msi_selected(dev) &&
            (lsf_prepaid_stream_msi_release_known(LSF_STREAM_MSI_CONTEXT, dr->node.release) ||
             lsf_prepaid_stream_msi_release_known(LSF_STREAM_MSI_GROUP, dr->node.release)))
            return -EOPNOTSUPP;
        return 0;
    }
    if (selected != 1 || !lsf_prepaid_stream_msi_release_known(role, dr->node.release) ||
        (phase == LSF_STREAM_MSI_UNLINKED && !list_empty(&dr->node.entry)) ||
        (phase == LSF_STREAM_MSI_BEFORE_RELEASE && list_empty(&dr->node.entry)))
        return -EOPNOTSUPP;
    if (role == LSF_STREAM_MSI_CONTEXT)
        selected = lsf_prepaid_stream_msi_payload_known(actual, dr->data, phase);
    else
        selected = lsf_prepaid_stream_msi_group_payload_known(dr->data, phase);
    return selected == 1 ? 1 : -EOPNOTSUPP;
}

int lsf_prepaid_stream_msi_devres_retire(struct device *dev, void *base, int phase)
{
    int result = lsf_prepaid_stream_msi_devres_validate(dev, base, phase);
    if (result == 1) result = lsf_factory_stream_msi_return(base, dev);
    if (result != 1) lsf_factory_stream_constructor_retain_unknown();
    return result;
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after the native private msi_device_data/group definitions. */
#include <net/lsf_stream_msi_context_private.h>

int lsf_prepaid_stream_msi_payload_geometry(unsigned long *bytes, unsigned long *alignment)
{
    if (!bytes || !alignment || __alignof__(struct msi_device_data) > 64u) return -EOPNOTSUPP;
    *bytes = sizeof(struct msi_device_data); *alignment = __alignof__(struct msi_device_data);
    return 0;
}

int lsf_prepaid_stream_msi_release_known(unsigned int role, void (*release)(struct device *, void *))
{
    return role == LSF_STREAM_MSI_CONTEXT ? release == msi_device_data_release :
        role == LSF_STREAM_MSI_GROUP ? lsf_prepaid_stream_msi_group_release_known(release) : 0;
}

int lsf_prepaid_stream_msi_group_known(const struct attribute_group *group)
{
#ifdef CONFIG_SYSFS
    return group == &msi_irqs_group && group->attrs == msi_dev_attrs && !msi_dev_attrs[0] &&
        !group->bin_attrs && !group->is_visible && !group->is_bin_visible &&
        !strcmp(group->name, "msi_irqs");
#else
    return 0;
#endif
}

int lsf_prepaid_stream_msi_payload_known(struct device *dev, const void *data, int phase)
{
    const struct msi_device_data *md = data;
    unsigned int i;
    if (phase == LSF_STREAM_MSI_UNLINKED || phase == LSF_STREAM_MSI_AFTER_RELEASE)
        return dev->msi.data == NULL;
    if (phase != LSF_STREAM_MSI_BEFORE_RELEASE || dev->msi.data != md) return 0;
    for (i = 0; i < MSI_MAX_DEVICE_IRQDOMAINS; ++i) {
        struct irq_domain *domain = md->__domains[i].domain;
        if (!xa_empty(&md->__domains[i].store) ||
            (domain && (domain != dev->msi.domain || irq_domain_is_msi_device(domain))))
            return 0;
    }
    /* The original callback only observes/removes EMPTY, non-device domains.
     * No per-device domain producer is admitted by this source stage. */
    return 1;
}

int lsf_prepaid_stream_msi_setup_device_data(struct device *dev)
{
#ifndef CONFIG_SYSFS
    return -EOPNOTSUPP;
#else
	struct msi_device_data *md;
	int ret, i;
	struct lsf_stream_msi_plan plan = {};

    if (dev->msi.data) {
        unsigned int role;
        if (lsf_prepaid_stream_msi_resource_classify(dev, dev->msi.data, &role) != 1 ||
            role != LSF_STREAM_MSI_CONTEXT) {
            lsf_factory_stream_constructor_retain_unknown(); return -EOPNOTSUPP;
        }
        return 0;
    }
    ret = lsf_factory_stream_msi_prepare(dev, &plan);
    if (ret != 1) return ret;

	md = lsf_prepaid_stream_msi_devres_allocate(dev, LSF_STREAM_MSI_CONTEXT, &plan, msi_device_data_release);
	if (!md) {
		lsf_factory_stream_msi_discard(dev, &plan);
		return -ENOMEM;
	}

	ret = lsf_prepaid_stream_msi_add_group(dev, &msi_irqs_group, &plan);
	if (ret) {
		devres_free(md);
		lsf_factory_stream_msi_discard(dev, &plan);
		return ret;
	}

	for (i = 0; i < MSI_MAX_DEVICE_IRQDOMAINS; i++)
		xa_init_flags(&md->__domains[i].store, XA_FLAGS_ALLOC);

	/*
	 * If @dev::msi::domain is set and is a global MSI domain, copy the
	 * pointer into the domain array so all code can operate on domain
	 * ids. The NULL pointer check is required to keep the legacy
	 * architecture specific PCI/MSI support working.
	 */
	if (dev->msi.domain && !irq_domain_is_msi_parent(dev->msi.domain))
		md->__domains[MSI_DEFAULT_DOMAIN].domain = dev->msi.domain;

	mutex_init(&md->mutex);
	dev->msi.data = md;
	devres_add(dev, md);
	lsf_factory_stream_msi_discard(dev, &plan);
	return 0;
#endif
}

/* SPDX-License-Identifier: GPL-2.0-only */
/* Included after actual device_attr_group_devres and its native callback. */
#include <net/lsf_stream_msi_context_private.h>

int lsf_prepaid_stream_msi_group_geometry(unsigned long *bytes, unsigned long *alignment)
{
    if (!bytes || !alignment || __alignof__(union device_attr_group_devres) > 64u)
        return -EOPNOTSUPP;
    *bytes = sizeof(union device_attr_group_devres);
    *alignment = __alignof__(union device_attr_group_devres);
    return 0;
}

int lsf_prepaid_stream_msi_group_release_known(void (*release)(struct device *, void *))
{
    return release == devm_attr_group_remove;
}

int lsf_prepaid_stream_msi_group_payload_known(const void *data, int phase)
{
    const union device_attr_group_devres *resource = data;
    if (phase == LSF_STREAM_MSI_UNLINKED && !resource->group) return 1;
    return lsf_prepaid_stream_msi_group_known(resource->group);
}

int lsf_prepaid_stream_msi_add_group(struct device *dev, const struct attribute_group *grp,
    const struct lsf_stream_msi_plan *plan)
{
	union device_attr_group_devres *devres;
	int error;

	if (!lsf_prepaid_stream_msi_group_known(grp) || lsf_factory_stream_msi_selected(dev) != 1)
		return -EOPNOTSUPP;

	devres = lsf_prepaid_stream_msi_devres_allocate(dev, LSF_STREAM_MSI_GROUP, plan, devm_attr_group_remove);
	if (!devres)
		return -ENOMEM;

	error = sysfs_create_group(&dev->kobj, grp);
	if (error) {
		devres_free(devres);
		return error;
	}

	devres->group = grp;
	devres_add(dev, devres);
	return 0;
}
